loop {
    let best = (0..n)
        .filter(|&v| !taken[v] && indegree[v] == 0)
        .min_by_key(|&v| names[v]);
    let Some(v) = best else {
        break;
    };
    order.push(names[v]);
    taken[v] = true;
}
if show_cycle {
    let mut remaining: Vec<&str> = (0..n).filter(|&v| !taken[v]).map(|v| names[v]).collect();
    remaining.sort();
    println!("cycle: {}", remaining.join(" "));
